import {chromium} from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1100, height: 900}, deviceScaleFactor: 1});

const errors = [];
page.on('console', (m) => {
    if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`);
});
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

const engineRequests = [];
page.on('request', (r) => {
    const u = r.url();
    if (/Engine|uplot|gravity|charts/i.test(u)) engineRequests.push(u.replace(URL, '/'));
});

await page.goto(URL, {waitUntil: 'networkidle'});
await page.waitForSelector('section[aria-label^="Динамика"]', {timeout: 30000});
await page.waitForSelector('section svg', {timeout: 30000});
await page.waitForTimeout(800);
const afterSales = engineRequests.length;
console.log('engine requests after first load (sales):', engineRequests.slice(0, afterSales));
await page.screenshot({path: '/tmp/viz-check/1-sales.png', fullPage: true});

await page.getByText('Мониторинг', {exact: true}).click();
await page.waitForSelector('.uplot canvas', {timeout: 30000});
await page.waitForTimeout(500);
console.log('engine requests after switching to monitoring:', engineRequests.slice(afterSales));
await page.screenshot({path: '/tmp/viz-check/2-monitoring.png', fullPage: true});

const over = await page.locator('.uplot .u-over').first().boundingBox();
if (over) {
    await page.mouse.move(over.x + over.width * 0.55, over.y + over.height * 0.4);
    await page.waitForTimeout(300);
    await page.screenshot({path: '/tmp/viz-check/3-monitoring-hover.png', fullPage: true});
}

// Back to sales: engine should come from cache, no new engine request.
const before = engineRequests.length;
await page.getByText('Продажи', {exact: true}).click();
await page.waitForSelector('section svg', {timeout: 30000});
await page.waitForTimeout(500);
console.log('new engine requests on switching back to sales:', engineRequests.length - before);
await page.screenshot({path: '/tmp/viz-check/4-sales-again.png', fullPage: true});

console.log('console/page errors:', errors.length ? errors : 'none');
await browser.close();

